window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-team-inbox.html"]="<!-- Settings: Team Inboxes -->\n<style>\n.ti-empty{text-align:center;padding:40px;color:var(--muted);font-size:13px}\n.ti-expand-row td{background:var(--bg);padding:0 !important}\n.ti-expand-body{padding:12px 20px;display:flex;flex-wrap:wrap;gap:8px}\n.ti-agent-chip{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;background:var(--card);border:1px solid var(--border);border-radius:16px;font-size:12px}\n.ti-agent-chip .dot{width:8px;height:8px;border-radius:50%}\n.ti-agent-chip .dot.online{background:#22c55e}.ti-agent-chip .dot.busy{background:#eab308}.ti-agent-chip .dot.offline{background:#94a3b8}\n.ti-agents-list{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}\n.ti-agent-check{display:flex;align-items:center;gap:6px;padding:6px 12px;border:1px solid var(--border);border-radius:8px;cursor:pointer;font-size:13px;transition:all .15s}\n.ti-agent-check.selected{border-color:var(--accent);background:rgba(79,70,229,.05)}\n.ti-agent-check input{margin:0}\n.ti-del-confirm{background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:12px;margin:10px 0;font-size:13px;color:var(--danger)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">⏱️ SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">⚡ Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">🟢 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">🔵 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">💬 Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px\">\n      <div>\n        <h2 style=\"margin:0 0 4px\">📥 Tim Inbox</h2>\n        <p style=\"color:var(--muted);font-size:13px;margin:0\">Kelola inbox per tim dengan agen dan SLA masing-masing.</p>\n      </div>\n      <button class=\"btn primary\" onclick=\"openTIModal()\">+ Buat Tim Inbox</button>\n    </div>\n\n    <table class=\"data-table\" id=\"tiTable\">\n      <thead><tr><th>Nama</th><th>Deskripsi</th><th>Agen</th><th>SLA (jam)</th><th></th></tr></thead>\n      <tbody id=\"tiBody\"></tbody>\n    </table>\n  </div>\n</div>\n\n<!-- Create/Edit Modal -->\n<div class=\"modal-overlay\" id=\"tiModal\">\n  <div class=\"modal\" style=\"max-width:520px\">\n    <h3 id=\"tiTitle\">Buat Tim Inbox</h3>\n    <label>Nama Tim<input id=\"tiName\" placeholder=\"Tim Support A\"></label>\n    <label>Deskripsi<input id=\"tiDesc\" placeholder=\"Support umum\"></label>\n    <label>SLA (jam)<input type=\"number\" id=\"tiSla\" min=\"1\" value=\"4\" style=\"width:100px\"></label>\n    <label style=\"margin-top:8px\">Pilih Agen</label>\n    <div class=\"ti-agents-list\" id=\"tiAgentList\"></div>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('tiModal')\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveTI()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<!-- Delete Confirm Modal -->\n<div class=\"modal-overlay\" id=\"tiDelModal\">\n  <div class=\"modal\">\n    <h3>Hapus Tim Inbox</h3>\n    <div class=\"ti-del-confirm\" id=\"tiDelMsg\"></div>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('tiDelModal')\">Batal</button>\n      <button class=\"btn danger\" onclick=\"doDeleteTI()\">Hapus</button>\n    </div>\n  </div>\n</div>\n\n<script>\nvar _editTI = null;\nvar _delTI = null;\nvar _expandedTI = null;\n\nfunction renderTI(){\n  const list = DB.settings.teamInboxes || [];\n  const tbody = document.getElementById('tiBody');\n  if(!list.length){\n    tbody.innerHTML = '<tr><td colspan=\"5\" class=\"ti-empty\">Belum ada tim inbox.</td></tr>';\n    return;\n  }\n  let html = '';\n  list.forEach(ti => {\n    const agentNames = (ti.agents||[]).map(uid => {\n      const a = DB.agents.find(x=>x.id===uid);\n      return a ? a.name : uid;\n    });\n    html += `<tr style=\"cursor:pointer\" onclick=\"toggleExpand('${ti.id}')\">\n      <td><strong>${ti.name}</strong></td>\n      <td style=\"font-size:12px;color:var(--muted)\">${ti.description||'-'}</td>\n      <td>${ti.agents.length} agen</td>\n      <td>${ti.sla} jam</td>\n      <td style=\"text-align:right;white-space:nowrap\">\n        <button class=\"btn\" onclick=\"event.stopPropagation();openEditTI('${ti.id}')\">✏️</button>\n        <button class=\"btn danger\" onclick=\"event.stopPropagation();openDelTI('${ti.id}')\">🗑️</button>\n      </td>\n    </tr>`;\n    if(_expandedTI === ti.id){\n      const chips = (ti.agents||[]).map(uid => {\n        const a = DB.agents.find(x=>x.id===uid);\n        if(!a) return '';\n        return `<span class=\"ti-agent-chip\"><span class=\"dot ${a.status}\"></span>${a.name}</span>`;\n      }).join('');\n      html += `<tr class=\"ti-expand-row\"><td colspan=\"5\"><div class=\"ti-expand-body\">${chips||'<span style=\"color:var(--muted);font-size:12px\">Belum ada agen</span>'}</div></td></tr>`;\n    }\n  });\n  tbody.innerHTML = html;\n}\n\nfunction toggleExpand(id){\n  _expandedTI = _expandedTI === id ? null : id;\n  renderTI();\n}\n\nfunction renderAgentChecks(selected){\n  const agents = DB.agents || [];\n  document.getElementById('tiAgentList').innerHTML = agents.map(a => `\n    <label class=\"ti-agent-check ${selected.includes(a.id)?'selected':''}\">\n      <input type=\"checkbox\" value=\"${a.id}\" ${selected.includes(a.id)?'checked':''} onchange=\"this.parentElement.classList.toggle('selected',this.checked)\">\n      ${a.name}\n    </label>\n  `).join('');\n}\n\nfunction getSelectedAgents(){\n  return [...document.querySelectorAll('#tiAgentList input:checked')].map(c=>c.value);\n}\n\nfunction openTIModal(){\n  _editTI = null;\n  document.getElementById('tiTitle').textContent = 'Buat Tim Inbox';\n  document.getElementById('tiName').value = '';\n  document.getElementById('tiDesc').value = '';\n  document.getElementById('tiSla').value = 4;\n  renderAgentChecks([]);\n  document.getElementById('tiModal').classList.add('open');\n}\n\nfunction openEditTI(id){\n  const ti = DB.settings.teamInboxes.find(x=>x.id===id);\n  if(!ti) return;\n  _editTI = id;\n  document.getElementById('tiTitle').textContent = 'Edit Tim Inbox';\n  document.getElementById('tiName').value = ti.name;\n  document.getElementById('tiDesc').value = ti.description || '';\n  document.getElementById('tiSla').value = ti.sla;\n  renderAgentChecks(ti.agents||[]);\n  document.getElementById('tiModal').classList.add('open');\n}\n\nfunction saveTI(){\n  const name = document.getElementById('tiName').value.trim();\n  if(!name){ showToast('Nama tim wajib diisi'); return; }\n  const data = {\n    name,\n    description: document.getElementById('tiDesc').value.trim(),\n    agents: getSelectedAgents(),\n    sla: parseInt(document.getElementById('tiSla').value)||4,\n  };\n  if(_editTI){\n    const i = DB.settings.teamInboxes.findIndex(x=>x.id===_editTI);\n    if(i>=0) DB.settings.teamInboxes[i] = {...DB.settings.teamInboxes[i], ...data};\n  } else {\n    DB.settings.teamInboxes.push({id:genId('ti'), ...data});\n  }\n  saveStore();\n  closeModal('tiModal');\n  renderTI();\n  showToast(_editTI ? 'Tim inbox diperbarui' : 'Tim inbox dibuat');\n}\n\nfunction openDelTI(id){\n  const ti = DB.settings.teamInboxes.find(x=>x.id===id);\n  if(!ti) return;\n  _delTI = id;\n  document.getElementById('tiDelMsg').textContent = `Yakin ingin menghapus tim inbox \"${ti.name}\"?`;\n  document.getElementById('tiDelModal').classList.add('open');\n}\n\nfunction doDeleteTI(){\n  DB.settings.teamInboxes = DB.settings.teamInboxes.filter(x=>x.id!==_delTI);\n  saveStore();\n  closeModal('tiDelModal');\n  renderTI();\n  showToast('Tim inbox dihapus');\n}\n\nrenderTI();\n</script>\n";
